#!/usr/bin/env bash
# shellcheck shell=bash
# Generated by kwisatz tasks/setup-gufo-strix-halo-qwen38-flash.sh from
# templates/gufo-strix-halo-qwen38-flash/gufo-prepare.sh — do not edit it here.
#
# What this is: the single source of truth for WHICH FILES this model needs,
# for both sides of the system:
#
#   --list-files   → the setup script's download gate asks what is missing
#   (no flag)      → the actual download
#
# That is the point. A second copy of the list in tasks/setup-*.sh would drift
# on the first upstream file rename and silently turn "cached" into "not
# cached" — i.e. a 95 GB re-download that the operator has to wait for and the
# task cannot explain.
#
# Idempotency: a re-run with everything present is a handful of `test`
# builtins and one `docker image inspect`. Nothing is re-fetched, because
# hf download only writes files it does not have.
#
# Patterns, not filenames: the checkpoint is sharded, so the "file" is a glob
# (`UD-Q4_K_XL/*.gguf`, or `Qwen3.8-27B-UD-Q4_K_XL*` where the repo ships one
# file per quant). huggingface_hub accepts those as --include patterns and the
# gate matches them with a shell glob, so the same string drives the download,
# the gate and serve. A repo that pushes one more shard needs no change here.
set -eu

STATE_DIR="${STATE_DIR_PATH}"
# The env file sits next to this wrapper, not in STATE_DIR. Sourcing it is what
# makes HF_CACHE and GUFO_IMAGE in .env the lever they are documented to be;
# without it this script silently falls back to the invoking user's cache, which
# for llama-swap's download step means root's.
if [[ -r "${GUFO_ENV_FILE}" ]]; then
  # shellcheck source=/dev/null
  source "${GUFO_ENV_FILE}"
else
  printf 'gufo-prepare.sh: cannot read %s — falling back to %s/.cache/huggingface; run tasks/setup-gufo-strix-halo-qwen38-flash.sh\n' \
    "${GUFO_ENV_FILE}" "${HOME:-/root}" >&2
fi

# ── The list ─────────────────────────────────────────────────────────────────
# One line per required file:  repo <TAB> pattern <TAB> required(1/0)
#
# required=1 is what `--list-files` reports, i.e. what makes a cache "usable".
# required=0 is fetched when present-but-optional (the sidecars: a model that
# runs without them still runs, and an operator who turns speculation off pays
# for them only once).
REQUIRED_FILES=(
  $'${GUFO_MODEL_REPO}\t${GUFO_SHARD_PATTERN}\t1'
  $'${GUFO_MODEL_REPO}\t${GUFO_MMPROJ_PATTERN}\t1'
)
# optional: fetched when missing, not required to call the cache usable
OPTIONAL_FILES=(
  $'${GUFO_MODEL_REPO}\t${GUFO_DRAFT_PATTERN}\t0'
)
# ── Snapshot and shard-set rules ────────────────────────────────────────
# Identical in gufo-serve.sh, and deliberately so: the gate in the setup script,
# the check below and the runtime all answer "what is cached?" with the same
# three lines of code, because the failure mode is them disagreeing. Copy,
# because a rendered wrapper cannot go looking in the repo for a library.
# (the ordering comment continues below)
# ── Snapshot ordering ───────────────────────────────────────────────────────
# Newest-first, by mtime. `ls -dt` would do it too, but ls output is not meant
# to be parsed and find's is: -printf gives us the timestamp and the path on
# one line, and the rest is a sort. A hand-placed or hand-updated snapshot then
# wins on the same rule as a downloaded one, instead of on name order.
snapshots_newest_first() {
  find "$1" -maxdepth 1 -mindepth 1 -type d -printf '%T@ %p\n' 2>/dev/null \
    | sort -rn | sed 's/^[0-9.]* //'
}

# ── Shard sets ───────────────────────────────────────────────────────────────
# A checkpoint is either one file or N files named <prefix>-00001-of-00004.gguf.
# The file name carries the count, so "is the whole thing here?" is free to ask,
# and asking is the point: the engine opens the file it is given, reads
# split.count out of that file's metadata and then looks its siblings up by
# name, so a partial set is a load failure whose error says nothing about the
# missing parts — which reads as "the model is broken" rather than "run the
# download again".
#
#   shard_set_state <snapshot-dir> <pattern>
#     -> "OK<TAB><first shard, relative to the snapshot>"
#     -> "PARTIAL<TAB><which file is missing>"
#     -> "NONE<TAB>"
#
# First shard, not first match: handing the engine shard 2 of a 4-part model
# would load the wrong tensors in silence, because the loader trusts the index
# it is handed. `sort` gets there by luck (zero-padded names), so the index is
# matched explicitly and the sort order is only the fallback for checkpoints
# that are not split at all.
shard_set_state() {
  local snap="$1" pattern="$2"
  local -a files=()
  mapfile -t files < <(compgen -G "${snap}/${pattern}" 2>/dev/null | sort)
  if [[ ${#files[@]} -eq 0 ]]; then
    printf 'NONE\t\n'
    return 0
  fi
  local first base prefix iw cw total n f dir
  first="${files[0]}"
  for f in "${files[@]}"; do
    base="${f##*/}"
    if [[ "$base" =~ ^(.*-)0*1-of-[0-9]+\.gguf$ ]]; then
      first="$f"
      break
    fi
  done
  # Sibling shards sit next to the file the glob matched, which may be a
  # checkpoint subdirectory rather than the snapshot root.
  dir="${first%/*}"
  base="${first##*/}"
  if [[ ! "$base" =~ ^(.*-)([0-9]+)-of-([0-9]+)\.gguf$ ]]; then
    printf 'OK\t%s\n' "${first#"$snap"/}"
    return 0
  fi
  prefix="${BASH_REMATCH[1]}"
  iw="${#BASH_REMATCH[2]}"
  cw="${#BASH_REMATCH[3]}"
  total=$((10#${BASH_REMATCH[3]}))
  for ((n = 1; n <= total; n++)); do
    f="${dir}/${prefix}$(printf '%0*d' "$iw" "$n")-of-$(printf '%0*d' "$cw" "$total").gguf"
    if [[ ! -e "$f" ]]; then
      printf 'PARTIAL\t%s is missing from %s (the glob found %d of %d)\n' \
        "$f" "$snap" "${#files[@]}" "$total"
      return 0
    fi
  done
  printf 'OK\t%s\n' "${first#"$snap"/}"
}


# strix_have_pattern <cache-dir> <pattern>
#   "Is it cached?" for both sides of this script. Newest snapshot first, and
#   the whole declared shard set must be present — see shard_set_state above.
#   Sets STRIX_PATTERN_WHY when it comes back false, so the reason travels with
#   the message instead of turning into "the checkpoint is corrupt" later.
STRIX_PATTERN_WHY=""
strix_have_pattern() {
  local cache="$1" pattern="$2"
  STRIX_PATTERN_WHY=""
  local d kind rest out
  if [[ ! -d "${cache}/snapshots" ]]; then
    STRIX_PATTERN_WHY="no cache dir for this repo yet"
    return 1
  fi
  while IFS= read -r d; do
    out="$(shard_set_state "$d" "$pattern")"
    IFS=$'\t' read -r kind rest <<<"$out"
    case "$kind" in
    OK) return 0 ;;
    PARTIAL)
      STRIX_PATTERN_WHY="$rest"
      ;;
    esac
  done < <(snapshots_newest_first "${cache}/snapshots")
  [[ -n "$STRIX_PATTERN_WHY" ]] || STRIX_PATTERN_WHY="nothing matched ${pattern}"
  return 1
}

REQUIRED_FILES+=("${OPTIONAL_FILES[@]}")
entry="" repo="" pattern="" req=""

# The cache this stack reads and writes. .env sets it; running the wrapper
# directly, without a rendered .env, falls back to the standard user cache.
HF_CACHE="${HF_CACHE:-${HOME:-/root}/.cache/huggingface}"

# Engine image this recipe was validated against. Pulled, not built.
GUFO_IMAGE="${GUFO_IMAGE:-${GUFO_IMAGE_DEFAULT}}"
CONTAINER_RUNTIME="${CONTAINER_RUNTIME:-docker}"
GUFO_REVISION="${GUFO_REVISION:-${GUFO_REVISION_DEFAULT}}"

# ── Modes ────────────────────────────────────────────────────────────────────
if [[ "${1:-}" == "--list-files" ]]; then
  for entry in "${REQUIRED_FILES[@]}"; do
    IFS=$'\t' read -r repo pattern req <<<"$entry"
    [[ "$req" == "1" ]] || continue
    printf '%s\t%s\n' "$repo" "$pattern"
  done
  exit 0
fi

if [[ "${1:-}" == "--check" ]]; then
  missing=0
  for entry in "${REQUIRED_FILES[@]}"; do
    IFS=$'\t' read -r repo pattern req <<<"$entry"
    [[ "$req" == "1" ]] || continue
    cache="${HF_CACHE}/hub/models--${repo//\//--}"
    if ! strix_have_pattern "$cache" "$pattern"; then
      echo "missing: ${repo} :: ${pattern}${STRIX_PATTERN_WHY:+ — ${STRIX_PATTERN_WHY}}" >&2
      missing=1
    fi
  done
  exit "$missing"
fi

log() { printf 'gufo-prepare.sh: %s\n' "$*"; }

# ── Download ─────────────────────────────────────────────────────────────────
if ! command -v hf >/dev/null 2>&1; then
  log "the huggingface CLI (hf) is not installed — install it first (tasks/setup-huggingface.sh)"
  exit 1
fi

# A gated repo needs HF_TOKEN present in the environment; public unsloth repos
# do not. Nothing here stores it.
if [[ -n "${HF_TOKEN:-}" ]]; then
  export HF_TOKEN
else
  log "HF_TOKEN not set: fine for public repos, needed for gated ones"
fi

mkdir -p -- "${STATE_DIR}"

for entry in "${REQUIRED_FILES[@]}"; do
  IFS=$'\t' read -r repo pattern req <<<"$entry"
  cache="${HF_CACHE}/hub/models--${repo//\//--}"
  if strix_have_pattern "$cache" "$pattern"; then
    continue
  fi
  log "downloading ${repo} :: ${pattern}${STRIX_PATTERN_WHY:+ (${STRIX_PATTERN_WHY})}"
  # --include, not a positional file name. The CLI treats the positional
  # argument as an exact path and URL-encodes the wildcard, so
  # `hf download repo "Qwen3.8-27B-UD-Q4_K_XL*"` asks the hub for a file named
  # `...UD-Q4_K_XL%2A` and fails with "File not found" — for every sharded
  # checkpoint, which is exactly the shape these patterns are.
  #
  # --cache-dir pins the destination to this stack's cache. Without it hf falls
  # back to the invoking user's own cache, and when llama-swap's own download
  # step runs this wrapper as root that means the weights land in
  # /root/.cache/huggingface while serve looks for them under $HF_CACHE: the
  # download "succeeds" and the model still cannot start.
  if [[ -n "$GUFO_REVISION" ]]; then
    hf download "$repo" --repo-type model --include "$pattern" \
      --cache-dir "${HF_CACHE}/hub" --revision "$GUFO_REVISION"
  else
    hf download "$repo" --repo-type model --include "$pattern" \
      --cache-dir "${HF_CACHE}/hub"
  fi
done

if ! "${CONTAINER_RUNTIME}" image inspect "${GUFO_IMAGE}" >/dev/null 2>&1; then
  log "pulling ${GUFO_IMAGE}"
  "${CONTAINER_RUNTIME}" pull "${GUFO_IMAGE}"
fi

# ── Marker ───────────────────────────────────────────────────────────────────
# Written last, and only after every required file verified present. That
# ordering is what makes "the marker exists" equal to "this is ready" for both
# llama-swap's download: step and the setup script's re-run.
if [[ -f "${STATE_DIR}/prepared" ]]; then
  log "already prepared"
else
  printf '%s\n' \
    "PREPARED_AT=$(date -u +%Y-%m-%dT%H:%M:%SZ)" \
    "ENGINE_IMAGE=${GUFO_IMAGE}" \
    "RUNTIME=${CONTAINER_RUNTIME}" \
    >"${STATE_DIR}/prepared"
  log "marker written: ${STATE_DIR}/prepared"
fi

# The resolved checkpoint *revisions* are recorded by the setup script into
# this same file, so that install, --check and the drift warning all read one
# place. Key naming lives in lib/strix-halo-helper.sh
# (strix_checkpoint_revision_record), not here, for exactly that reason.
